// spec: portals
// Portals: порталы пустоты на камне экрана — шанс «a из b» на генераторе игры, бросок портала, зона руды.
// Код по спеке oracle/specs/portals.md (правила 0–5). Данные — data/systems/portals.json, передаёт вызывающий.

const MASK63 = (1n << 63n) - 1n;

/** @param {object} data содержимое data/systems/portals.json */
export function makePortals(data) {
  const C = data.constants;
  const eps = C['compare.eps'];
  const zones = new Map(data.tables.oreZone.rows.map((r) => [r[0], r[1]]));

  // правило 1: ровно 2 слова генератора игры
  function chance(a, b, g) {
    const w1 = BigInt(g.u32());
    const w2 = BigInt(g.u32());
    const u = ((w2 << 32n) | w1) & MASK63;
    const m = Number(u % BigInt(Math.trunc(b)));
    return !((m + 1) - a > eps);
  }

  // правило 5
  function zoneOf(ore) {
    return zones.has(ore) ? zones.get(ore) : C['zone.default'];
  }

  // правило 2
  function roll(g, chances, ore) {
    const [v, gl, r, x] = chances;
    const out = { void: false, golden: false, rainbow: false, galactic: false, ore };
    if (!(v - 0 > eps)) return out;
    if (!chance(v, C['void.die'], g)) return out;
    out.void = true;
    const k = C['sub.scale'];
    const die = C['sub.die'];
    if (gl - 0 > eps) out.golden = chance(k * gl, die, g);
    if (out.golden) {
      out.rainbow = chance(k * r, die, g);
      if (out.rainbow) out.galactic = chance(k * x, die, g);
    }
    out.ore = g.irandomRange(C['ore.low'], ore);
    return out;
  }

  return { chance, roll, zoneOf };
}
EOF
